// MK4 — Browser storage adapter + dev-server log sink. Platform glue only:
// no game rules live here. The logic layer produces serialized saves and log
// entries; this module persists them (localStorage) and, in dev, mirrors log
// entries to the Vite middleware sink so they land in a text file on the dev
// machine — including entries generated by a phone playing over the LAN.

import { DEFAULT_BATTLE_SETTINGS } from './logic/constants';
import { GAME_VERSION } from './logic/data/content';
import {
  BattleEventEntry,
  LOGGING_SCHEMA_VERSION,
  LOG_BUDGET_BYTES,
  LoggingLevel,
  MAX_EVENT_LOG_ENTRIES,
  MAX_METRIC_LOG_ENTRIES,
  MAX_SELECTION_LOG_ENTRIES,
  MAX_TURN_LOG_ENTRIES,
  MAX_WIZARD_LOG_ENTRIES,
  MetricLogEntry,
  SelectionLogEntry,
  TurnLogEntry,
  WizardLogEntry,
  isLoggingLevel,
  loggingLevel,
} from './logic/logger';
import { BattleSettings } from './logic/types';

const SAVE_KEY = 'breach:save';
const METRICS_LOG_KEY = 'breach:log:metrics';
const TURN_LOG_KEY = 'breach:log:turns';
const WIZARD_LOG_KEY = 'breach:log:wizard'; // Alpha 0.2.0 §5.4 wizard records
const SELECTION_LOG_KEY = 'breach:log:selection'; // Alpha 0.3.0 §21.2
// Alpha 0.4.1 §4.3 — high-value battle events (routes/targeted/drains), and
// the fingerprint-keyed ContentStamp table they and metrics records join to.
const EVENT_LOG_KEY = 'breach:log:events';
const CONTENT_TABLE_KEY = 'breach:log:content';
const LOG_META_KEY = 'breach:log:meta'; // schema version + level preference
const CONFIG_KEY = 'breach:config';
// Every persisted LOG key, in ascending trim priority: index 0 is sacrificed
// first under budget pressure (§9). Metrics and committed selection records
// are the last to go — they carry the most analytical value per byte and are
// what child records join to.
const LOG_KEYS_BY_TRIM_ORDER = [TURN_LOG_KEY, EVENT_LOG_KEY, WIZARD_LOG_KEY, SELECTION_LOG_KEY, METRICS_LOG_KEY];
const ALL_LOG_KEYS = [...LOG_KEYS_BY_TRIM_ORDER, CONTENT_TABLE_KEY];
// Alpha 0.4.0 §9.4/§17.6 — the remembered Constructed Quick Match build.
// Deliberately its OWN key: convenience preference data, versioned separately,
// never competing for the single active save slot and never cleared by Run
// completion or abandonment.
const CONSTRUCTED_PRESET_KEY = 'breach:pref:constructed';
// (caps now live centrally in logic/logger.ts — §12.1)

function readArray<T>(key: string): T[] {
  try {
    const raw = localStorage.getItem(key);
    const arr = raw ? (JSON.parse(raw) as T[]) : [];
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

// ============================================================================
// Alpha 0.4.1 §12/§14/§15 — BUDGETED LOG PERSISTENCE
//
// Alpha 0.4 wrote each stream as one unbounded array and only reacted to
// quota AFTER a failed setItem. Retention is now enforced BEFORE the write,
// against both a per-stream entry cap and one shared byte budget, so a quota
// failure stops being the normal trimming trigger.
//
// Deliberate deviation from the supplement's §13 chunked-segment design: after
// compaction the streams are small enough (see the final report) that a whole
// stream is itself a bounded write, so segmenting would add an index, orphan
// handling, and corruption modes for no measured gain. The bounded-write
// PROPERTY is achieved by construction — caps bound each value's size — rather
// than by an extra storage layer. Revisit if measured sizes grow.
// ============================================================================

// §12 — conservative: at least two bytes per code unit, plus the key itself.
function estimateBytes(key: string, value: string): number {
  return (key.length + value.length) * 2;
}

function estimatedLogFootprint(exclude?: string): number {
  let total = 0;
  for (const k of ALL_LOG_KEYS) {
    if (k === exclude) continue;
    try {
      const v = localStorage.getItem(k);
      if (v) total += estimateBytes(k, v);
    } catch {
      /* unreadable key contributes nothing to the estimate */
    }
  }
  return total;
}

// True once a storage failure has survived an emergency trim and a retry:
// lower-priority persistence is off for the rest of the session (§15.4-15.7).
let lowPriorityLoggingDisabled = false;
let failureReported = false;

function reportLoggingFailure(reason: string): void {
  if (failureReported) return;
  failureReported = true;
  console.warn(`[breach] persisted logging degraded — ${reason}. Gameplay is unaffected.`);
}

// §9 — drop the oldest half of the lowest-priority stream that still has
// content. Returns false when nothing further can be surrendered.
function trimLowestPriorityStream(protectKey: string): boolean {
  for (const key of LOG_KEYS_BY_TRIM_ORDER) {
    const arr = readArray<unknown>(key);
    if (!arr.length) continue;
    if (key === protectKey && arr.length <= 1) continue;
    const kept = arr.slice(Math.ceil(arr.length / 2));
    try {
      if (kept.length) localStorage.setItem(key, JSON.stringify(kept));
      else localStorage.removeItem(key);
      return true;
    } catch {
      try {
        localStorage.removeItem(key);
        return true;
      } catch {
        /* fall through to the next stream */
      }
    }
  }
  return false;
}

// §14 — enforce the entry cap, then the byte budget, THEN write.
function writeArray<T>(key: string, arr: T[], cap: number, priority = 0): void {
  if (lowPriorityLoggingDisabled && priority < 2) return;
  let trimmed = arr.length > cap ? arr.slice(arr.length - cap) : arr;
  let payload = JSON.stringify(trimmed);
  const others = estimatedLogFootprint(key);

  // §14.1-14.4 — shed oldest records from THIS stream until the projected
  // total fits, then, if still over, shed from lower-priority streams.
  let guard = 0;
  while (others + estimateBytes(key, payload) > LOG_BUDGET_BYTES && guard++ < 64) {
    if (trimmed.length > 1) {
      trimmed = trimmed.slice(Math.ceil(trimmed.length / 4) || 1);
      payload = JSON.stringify(trimmed);
      continue;
    }
    if (!trimLowestPriorityStream(key)) break;
    return writeArray(key, trimmed, cap, priority);
  }

  try {
    localStorage.setItem(key, payload);
  } catch {
    // §15 — preflight said it should fit, so this is a real quota surprise:
    // exactly one emergency trim and one retry, then stop trying this session.
    if (trimLowestPriorityStream(key)) {
      try {
        localStorage.setItem(key, payload);
        return;
      } catch {
        /* fall through */
      }
    }
    lowPriorityLoggingDisabled = true;
    reportLoggingFailure('browser storage rejected a log write after trimming');
  }
}

// ---- MK4.1 save/restore ----

export function saveBattle(json: string, turn: number): void {
  try {
    localStorage.setItem(SAVE_KEY, json);
    console.info(`[breach] state saved (turn ${turn})`);
  } catch (e) {
    console.warn('[breach] autosave failed', e);
  }
}

export function loadBattleJson(): string | null {
  try {
    return localStorage.getItem(SAVE_KEY);
  } catch {
    return null;
  }
}

export function clearBattleSave(): void {
  try {
    localStorage.removeItem(SAVE_KEY);
  } catch {
    /* ignore */
  }
}

// ---- Alpha 0.4.0 §9.4 remembered Constructed build ----

export function saveConstructedPreset(json: string): void {
  try {
    localStorage.setItem(CONSTRUCTED_PRESET_KEY, json);
  } catch {
    /* a convenience preference must never break the game */
  }
}

export function loadConstructedPreset(): string | null {
  try {
    return localStorage.getItem(CONSTRUCTED_PRESET_KEY);
  } catch {
    return null;
  }
}

// ---- MK5.4 menu-settings persistence (persists across sessions; nothing
// resets it implicitly — "Reset to Defaults" in the UI is the only reset) ----

// Alpha 0.3.0 (cfgV 5): the persisted shape is now BattleSettings — the
// player-CHOSEN values only. Removed: `hackerBonusEnabled` (that passive is now
// the Hacker's Skill records, §6.1) and the persisted `strongColors`/
// `strongShapes` (resolved per battle from the selected Hacker, §5.4).
// Renamed: `noMatchDamage` -> `reinforcedConnection` (§11.1),
// `nmdChargeAwareBot` -> `reinforcedChargeAwareBot`, and `playerHp`/`enemyHp` ->
// `manualHackerLink`/`manualSystemIce` (used only when Normal LINK is OFF).
// Obsolete persisted fields from earlier builds are ignored without crashing:
// the migration copies surviving fields explicitly and carries the old
// no-match-damage / manual-HP values forward so a player's choices survive.
const MENU_CONFIG_VERSION = 5;

export function loadMenuSettings(): BattleSettings {
  try {
    const raw = localStorage.getItem(CONFIG_KEY);
    if (!raw) return { ...DEFAULT_BATTLE_SETTINGS };
    const c = JSON.parse(raw) as Partial<BattleSettings> & {
      cfgV?: number;
      // pre-0.3.0 field names, read for one-way migration only
      noMatchDamage?: unknown;
      nmdChargeAwareBot?: unknown;
      playerHp?: unknown;
      enemyHp?: unknown;
    };
    const bool = (v: unknown, fallback: boolean): boolean => (typeof v === 'boolean' ? v : fallback);
    const int = (v: unknown, min: number, max: number, fallback: number): number =>
      Number.isInteger(v) && (v as number) >= min && (v as number) <= max ? (v as number) : fallback;
    const D = DEFAULT_BATTLE_SETTINGS;
    const cfg: BattleSettings = {
      enemyMatching: bool(c.enemyMatching, D.enemyMatching),
      singleAxisPayout: bool(c.singleAxisPayout, D.singleAxisPayout),
      maxCascadeSteps:
        c.maxCascadeSteps === null || (Number.isInteger(c.maxCascadeSteps) && (c.maxCascadeSteps as number) >= 0 && (c.maxCascadeSteps as number) <= 9)
          ? (c.maxCascadeSteps as number | null)
          : D.maxCascadeSteps,
      // §11.1 — reuse the existing setting path rather than adding a second toggle
      reinforcedConnection: bool(c.reinforcedConnection, bool(c.noMatchDamage, D.reinforcedConnection)),
      normalLink: bool(c.normalLink, D.normalLink),
      manualHackerLink: int(c.manualHackerLink, 1, 9999, int(c.playerHp, 1, 9999, D.manualHackerLink)),
      manualSystemIce: int(c.manualSystemIce, 1, 9999, int(c.enemyHp, 1, 9999, D.manualSystemIce)),
      hintEnabled: bool(c.hintEnabled, D.hintEnabled),
      hintDelaySeconds: int(c.hintDelaySeconds, 1, 60, D.hintDelaySeconds),
      reinforcedChargeAwareBot: bool(c.reinforcedChargeAwareBot, bool(c.nmdChargeAwareBot, D.reinforcedChargeAwareBot)),
    };
    if (c.cfgV !== MENU_CONFIG_VERSION) {
      // Re-stamp so migration never re-runs, and so obsolete fields (dropped by
      // the explicit field copy above) are not re-persisted.
      saveMenuSettings(cfg);
    }
    return cfg;
  } catch {
    return { ...DEFAULT_BATTLE_SETTINGS };
  }
}

export function saveMenuSettings(c: BattleSettings): void {
  try {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ ...c, cfgV: MENU_CONFIG_VERSION }));
  } catch {
    /* ignore */
  }
}

// ---- MK4.3 log persistence ----

function postToSink(kind: 'metrics' | 'turn' | 'wizard' | 'selection' | 'event', entry: unknown): void {
  // dev-server sink only exists under `npm run dev`; guarded so non-Vite
  // runtimes (tests) can import this module safely
  if (!(import.meta as { env?: { DEV?: boolean } }).env?.DEV) return;
  void fetch('/__breach/log', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ kind, at: new Date().toISOString(), entry }),
  }).catch(() => {
    /* sink unreachable (e.g. preview build) — localStorage still has the logs */
  });
}

// §4.1 — the ContentStamp is identical for every battle sharing a fingerprint
// (788 B, ~21% of a metrics record in Alpha 0.4). Store it once per fingerprint
// and let metrics records reference it.
function rememberContentStamp(entry: MetricLogEntry): void {
  if (!entry.content) return;
  try {
    const table = JSON.parse(localStorage.getItem(CONTENT_TABLE_KEY) || '{}') as Record<string, unknown>;
    if (table[entry.fp]) return;
    table[entry.fp] = entry.content;
    localStorage.setItem(CONTENT_TABLE_KEY, JSON.stringify(table));
  } catch {
    /* the stamp is a convenience join; failing to cache it is not fatal */
  }
}

export function appendMetricsLog(entry: MetricLogEntry): void {
  rememberContentStamp(entry);
  // stored without the (now deduplicated) content stamp
  const { content, ...compact } = entry;
  const arr = readArray<MetricLogEntry>(METRICS_LOG_KEY);
  arr.push(compact as MetricLogEntry);
  // priority 2 — metrics are the last stream to be sacrificed (§9.1).
  writeArray(METRICS_LOG_KEY, arr, MAX_METRIC_LOG_ENTRIES, 2);
  postToSink('metrics', entry);
}

export function appendTurnLogs(entries: TurnLogEntry[]): void {
  if (!entries.length) return;
  const arr = readArray<TurnLogEntry>(TURN_LOG_KEY);
  arr.push(...entries);
  // §11 — the turn cap depends on the level the records were written under.
  writeArray(TURN_LOG_KEY, arr, MAX_TURN_LOG_ENTRIES[loggingLevel()]);
  for (const e of entries) postToSink('turn', e);
}

// §4.3 — routes, targeted Functions, and Drains. Written at every level,
// because BASIC has no turn stream for them to live in.
export function appendEventLogs(entries: BattleEventEntry[]): void {
  if (!entries.length) return;
  const arr = readArray<BattleEventEntry>(EVENT_LOG_KEY);
  arr.push(...entries);
  writeArray(EVENT_LOG_KEY, arr, MAX_EVENT_LOG_ENTRIES, 1);
  for (const e of entries) postToSink('event', e);
}

// Alpha 0.2.0 §5.4/§21.4 — wizard invocations are their own record stream,
// preserved alongside (never overwriting) the natural battle outcome.
export function appendWizardLog(entry: WizardLogEntry): void {
  const arr = readArray<WizardLogEntry>(WIZARD_LOG_KEY);
  arr.push(entry);
  writeArray(WIZARD_LOG_KEY, arr, MAX_WIZARD_LOG_ENTRIES, 1);
  postToSink('wizard', entry);
}

// Alpha 0.3.0 §21.2 — COMMITTED selection events and final Run creation.
export function appendSelectionLog(entry: SelectionLogEntry): void {
  const arr = readArray<SelectionLogEntry>(SELECTION_LOG_KEY);
  arr.push(entry);
  writeArray(SELECTION_LOG_KEY, arr, MAX_SELECTION_LOG_ENTRIES, 2);
  postToSink('selection', entry);
}

// ---- Alpha 0.4.1 §3.1 logging-level preference ----
// Versioned, validated, and stored apart from the active save. An unknown or
// corrupt value falls back to the environment default rather than blocking.

function environmentDefaultLevel(): LoggingLevel {
  return (import.meta as { env?: { DEV?: boolean } }).env?.DEV ? 'VERBOSE' : 'BASIC';
}

export function loadLoggingLevel(): LoggingLevel {
  try {
    const meta = JSON.parse(localStorage.getItem(LOG_META_KEY) || '{}') as { ls?: number; level?: unknown };
    if (meta.ls === LOGGING_SCHEMA_VERSION && isLoggingLevel(meta.level)) return meta.level;
  } catch {
    /* fall through to the environment default */
  }
  return environmentDefaultLevel();
}

export function saveLoggingLevel(level: LoggingLevel): void {
  try {
    localStorage.setItem(LOG_META_KEY, JSON.stringify({ ls: LOGGING_SCHEMA_VERSION, level }));
  } catch {
    /* a preference write failure must not break the game */
  }
}

// §18 — legacy Alpha 0.4 logs. The four streams live under independent keys,
// so the boundary is clean: the turn history carried the incompatible fat
// shape and is cleared once; metrics, selection, and wizard records remain
// structurally valid and are retained. Returns a description for diagnostics.
export function migrateLegacyLogs(): string | null {
  try {
    const meta = JSON.parse(localStorage.getItem(LOG_META_KEY) || '{}') as { ls?: number };
    if (meta.ls === LOGGING_SCHEMA_VERSION) return null; // already migrated
    const legacy = readArray<{ ls?: number }>(TURN_LOG_KEY);
    const stale = legacy.filter((e) => e?.ls !== LOGGING_SCHEMA_VERSION).length;
    if (stale > 0) localStorage.removeItem(TURN_LOG_KEY);
    localStorage.setItem(
      LOG_META_KEY,
      JSON.stringify({ ls: LOGGING_SCHEMA_VERSION, level: environmentDefaultLevel() }),
    );
    return stale > 0
      ? `cleared ${stale} pre-0.4.1 turn record(s); retained metrics, selection and wizard streams`
      : null;
  } catch {
    return null;
  }
}

// §19 — the export envelope. Identifies schema, level, retention, and the
// measured footprint so a dump is interpretable on its own, and resolves the
// deduplicated ContentStamp table back onto its metrics records.
export function readLogs(): {
  envelope: {
    gameVersion: string;
    loggingSchema: number;
    exportedAt: string;
    activeLevel: LoggingLevel;
    levelsPresent: LoggingLevel[];
    retention: Record<string, number | Record<string, number>>;
    estimatedBytes: number;
    lowPriorityDisabled: boolean;
  };
  content: Record<string, unknown>;
  metrics: MetricLogEntry[];
  turns: TurnLogEntry[];
  events: BattleEventEntry[];
  wizard: WizardLogEntry[];
  selection: SelectionLogEntry[];
} {
  const metrics = readArray<MetricLogEntry>(METRICS_LOG_KEY);
  const turns = readArray<TurnLogEntry>(TURN_LOG_KEY);
  const events = readArray<BattleEventEntry>(EVENT_LOG_KEY);
  const levels = new Set<LoggingLevel>();
  for (const r of [...metrics, ...turns, ...events]) if (isLoggingLevel(r?.lvl)) levels.add(r.lvl);
  let content: Record<string, unknown> = {};
  try {
    content = JSON.parse(localStorage.getItem(CONTENT_TABLE_KEY) || '{}') as Record<string, unknown>;
  } catch {
    content = {};
  }
  return {
    envelope: {
      gameVersion: GAME_VERSION,
      loggingSchema: LOGGING_SCHEMA_VERSION,
      exportedAt: new Date().toISOString(),
      activeLevel: loggingLevel(),
      levelsPresent: [...levels],
      retention: {
        budgetBytes: LOG_BUDGET_BYTES,
        metrics: MAX_METRIC_LOG_ENTRIES,
        events: MAX_EVENT_LOG_ENTRIES,
        selection: MAX_SELECTION_LOG_ENTRIES,
        wizard: MAX_WIZARD_LOG_ENTRIES,
        turnsByLevel: MAX_TURN_LOG_ENTRIES,
      },
      estimatedBytes: estimatedLogFootprint(),
      lowPriorityDisabled: lowPriorityLoggingDisabled,
    },
    content,
    metrics,
    turns,
    events,
    wizard: readArray(WIZARD_LOG_KEY),
    selection: readArray(SELECTION_LOG_KEY),
  };
}

// §16 — clearing logs must never touch the active save or non-log preferences.
export function wipeLogs(): void {
  for (const k of ALL_LOG_KEYS) {
    try {
      localStorage.removeItem(k);
    } catch {
      /* ignore */
    }
  }
}
